insert into public.deals (external_key, date, date_text, kind, asset_class, sport, target, target_kind, target_country, target_team_id, target_company_id, investor, investor_type, investor_company_id, investor_id, seller, stake_pct, amount, currency, valuation, valuation_currency, headline, summary, source_name, source_url, source)
  values ('deal:brighton-hove-albion-football-club:tony-bloom:2024-25-season', null, '2024-25 season', 'debt_financing', 'sports', 'football', 'Brighton & Hove Albion Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--brighton-hove-albion'), null, 'Tony Bloom', 'individual', (select id from public.companies where lower(name) = lower('Tony Bloom') limit 1), (select id from public.sports_investors where lower(name) = lower('Tony Bloom') limit 1), null, null, 107000000, 'GBP', null, null, 'Tony Bloom lends club £107m in 2024-25, taking owner loans to £406.5m', 'Per the 2024-25 accounts, owner Tony Bloom loaned the club £107m during the season, taking the interest-free shareholder loan balance to £406.5m after £109.8m had been repaid across the profitable 2022-23 and 2023-24 seasons.', 'WeAreBrighton (2024-25 accounts analysis)', 'https://www.wearebrighton.com/newsopinion/55-8m-loss-but-what-else-did-we-learn-from-brighton-2024-25-accounts/', 'web_research')
